//! Red/System: `azul.reds` (generated by `doc/src/codegen/v2/lang_red`,
//! `#include %azul.reds`).
//!
//! The bindings `#import` every C function under its C name
//! (`AzCssProperty_width`), but declare every tagged union as an 8-byte
//! opaque placeholder (`AzCssProperty!: alias struct! [opaque [byte-ptr!]]`,
//! marked TODO in the generator), and every CSS property is a tagged union
//! passed and returned BY VALUE. No property can therefore cross the FFI
//! with the right size, so this printer reports each style as not
//! expressible (with the reason) instead of emitting calls that would
//! corrupt the stack. The spellings below are the bindings' own and are
//! ready for when `lang_red` emits real union layouts.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{item_comments, item_doc, variant_ctor_method, ExprSyntax},
    CodegenBackend, GeneratedFile,
};

/// The Red/System printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Red;

/// `(f a b)`: Red/System calls are prefix, parenthesized when nested.
fn form(f: String, args: Vec<Doc>) -> Doc {
    if args.is_empty() {
        return Doc::text(f);
    }
    let mut parts = vec![Doc::text(format!("({f}"))];
    for a in args {
        parts.push(Doc::text(" "));
        parts.push(a);
    }
    parts.push(Doc::text(")"));
    Doc::cat(parts)
}

impl ExprSyntax for Red {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        if ty == Prim::F64 {
            text.to_string()
        } else {
            format!("as float32! {text}")
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("(mk-str \"{}\")", s.replace('^', "^^").replace('"', "^\"")))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, _broken: bool) -> Doc {
        form(format!("Az{class}_{}", snake_to_lower_camel(method)), args)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, _broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}_{variant}")),
            _ => form(format!("Az{ty}_{}", variant_ctor_method(variant)), args),
        }
    }

    fn strukt(&self, ty: &str, _fields: Vec<(String, Doc)>, _broken: bool) -> Doc {
        Doc::text(format!("(declare Az{ty}!)"))
    }

    fn vec(&self, ty: &str, _elem: &str, _items: Vec<Doc>, _broken: bool) -> Doc {
        Doc::text(format!("(Az{ty}_create)"))
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!(";; not expressible: {what}"))
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Int { .. }
            | Expr::Float { .. }
            | Expr::Bool(_)
            | Expr::Variant {
                shape: EnumShape::CLike,
                ..
            } => None,
            _ => Some(UNION_REASON.to_string()),
        }
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        Some(DOM_REASON)
    }
}

/// Why the Red/System printer does not export a DOM. (F1 sized the
/// binding's unions like C, but in LP64 units: `usize` / `u64` fields and
/// union blobs are pointer-width `byte-ptr!` slots.)
const DOM_REASON: &str = "Red/System builds 32-bit executables only, which cannot load the \
                          64-bit libazul whose LP64 layouts the binding mirrors (usize and u64 \
                          as pointer-width slots), so no Dom can cross the FFI by value";

const UNION_REASON: &str = "the Red/System bindings declare every tagged union (CssProperty, \
                            LayoutWidth, ...) as an 8-byte opaque placeholder, so no CSS \
                            property can be passed or returned by value";

fn item_fn(item: &Item) -> (bool, String) {
    let name = item.name.kebab();
    let mut out = String::new();
    match item_doc(&Red, item) {
        Ok(doc) => {
            for line in &item_comments(&Red, item) {
                out.push_str(&format!(";; {line}\n"));
            }
            out.push_str(&format!(
                "{name}: func [return: [Az{}! value]][\n    {}\n]\n",
                item.ty,
                render(&doc, "    ", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            // one line for the whole style (not one note per property)
            for line in &item.doc {
                out.push_str(&format!(";; {line}\n"));
            }
            out.push_str(&format!(
                ";; {name}: not expressible with the Red/System bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for Red {
    fn lang(&self) -> &'static str {
        "red"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["reds", "red-system"]
    }

    fn display_name(&self) -> &'static str {
        "Red/System"
    }

    fn extension(&self) -> &'static str {
        "red"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            ";; Generated by azul-css codegen (Red/System). Do not edit by hand.\n;; Include \
             after azul.reds: #include %styles.reds\n",
        );
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let built = m.items.iter().filter(|i| item_fn(i).0).count();
        let main = format!(
            "Red/System [\n    Title: \"azul-css styles\"\n    Purpose: {{Copy \
             target/codegen/azul.reds and libazul here, then: redc -r main.red}}\n]\n\n#include \
             %azul.reds\n#include %styles.reds\n\nprint-line \"styles expressible with these \
             bindings: {built}\"\n"
        );
        vec![
            GeneratedFile {
                path: "styles.reds".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.red".to_string(),
                contents: main,
            },
        ]
    }
}
